<?php
namespace Tests\Feature;
use App\Services\{Wallet,Identity,LocalSchedule,Notifications};
use App\Support\Json;
use Database\Seeders\DatabaseSeeder;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{DB,Hash,Http,Cache,Event};
use Illuminate\Support\Str;
use Tests\TestCase;

final class BackendTest extends TestCase {
    use RefreshDatabase;
    protected function setUp(): void {parent::setUp();$this->seed(DatabaseSeeder::class);Http::preventStrayRequests();Http::fake(['api.pwnedpasswords.com/*'=>Http::response(str_repeat('0',35).':0',200)]);}
    private function guest(): array {return $this->postJson('/api/v1/auth/guest',['device_name'=>'Test Android','device_id'=>(string)Str::uuid(),'platform'=>'android'])->assertCreated()->json();}
    private function headers(array $user,?string $key=null): array {return ['Authorization'=>'Bearer '.$user['access_token'],'Idempotency-Key'=>$key??(string)Str::uuid()];}
    private function start(array $u,string $level='green_valley_house_001',bool $offline=false): array {return $this->postJson('/api/v1/attempts',['level_id'=>$level,'offline'=>$offline],$this->headers($u))->assertCreated()->json();}
    private function events(string $attempt): array {$a=DB::table('attempts')->where('id',$attempt)->first();return array_map(fn($p)=>['event_id'=>(string)Str::uuid(),'piece_id'=>$p['id'],'anchor'=>$p['snap_anchor_px']],Json::read($a->snapshot)['manifest']['pieces']);}
    private function complete(array $u,string $id): array {return $this->postJson('/api/v1/attempts/'.$id.'/events',['events'=>$this->events($id)],$this->headers($u))->assertOk()->json();}
    public function test_launch_catalog_uses_only_approved_content(): void {$u=$this->guest();$data=$this->getJson('/api/v1/catalog',$this->headers($u))->assertOk()->json('catalog');$this->assertCount(5,$data['levels']);$this->assertSame([16,16,36,64,100],array_column($data['levels'],'piece_count'));$this->assertSame([360,360,600,1080,1800],array_column($data['levels'],'level_time_limit_seconds'));$this->assertFalse($data['worlds'][1]['published']);$this->assertFalse($data['levels'][1]['unlocked']);}
    public function test_guest_starting_grant_is_recorded_once(): void {$u=$this->guest();$this->assertSame(300,$u['player']['wallet']['coins']);app(Wallet::class)->initial($u['player']['id']);$this->assertSame(300,app(Wallet::class)->balance($u['player']['id'])['coins']);$this->assertDatabaseCount('ledger',1);}
    public function test_purchase_retries_are_idempotent_and_payload_reuse_conflicts(): void {$u=$this->guest();$key=(string)Str::uuid();$headers=$this->headers($u,$key);$this->postJson('/api/v1/shop/purchases',['offer_id'=>'hint_pack'],$headers)->assertOk()->assertJsonPath('wallet.coins',200);$this->postJson('/api/v1/shop/purchases',['offer_id'=>'hint_pack'],$headers)->assertOk()->assertHeader('Idempotency-Replayed','true')->assertJsonPath('wallet.hints',3);$this->postJson('/api/v1/shop/purchases',['offer_id'=>'shuffle_pack'],$headers)->assertConflict();$this->assertSame(200,app(Wallet::class)->balance($u['player']['id'])['coins']);}
    public function test_insufficient_purchase_rolls_back_every_financial_change(): void {$u=$this->guest();$this->postJson('/api/v1/shop/purchases',['offer_id'=>'starter_pack'],$this->headers($u))->assertConflict();$this->assertSame(300,app(Wallet::class)->balance($u['player']['id'])['coins']);$this->assertDatabaseCount('claims',0);$this->assertDatabaseCount('ledger',1);}
    public function test_locked_level_and_cross_player_attempt_are_denied(): void {$u=$this->guest();$other=$this->guest();$this->postJson('/api/v1/attempts',['level_id'=>'level_002_windmill_spring'],$this->headers($u))->assertForbidden();$a=$this->start($u);$this->getJson('/api/v1/attempts/'.$a['id'],$this->headers($other))->assertNotFound();}
    public function test_completion_grants_500_once_and_replay_only_improves_rating(): void {$u=$this->guest();$a=$this->start($u);$result=$this->complete($u,$a['id']);$this->assertSame('completed',$result['state']);$this->assertSame(3,$result['rating']);$this->assertSame(800,$result['wallet']['coins']);$replay=$this->start($u);$this->complete($u,$replay['id']);$this->assertSame(800,app(Wallet::class)->balance($u['player']['id'])['coins']);$this->assertSame(3,(int)DB::table('progress')->where('user_id',$u['player']['id'])->sum('best_stars'));}
    public function test_invalid_snap_does_not_place_or_grant(): void {$u=$this->guest();$a=$this->start($u);$events=$this->events($a['id']);$events[0]['anchor']=[9999,9999];$this->postJson('/api/v1/attempts/'.$a['id'].'/events',['events'=>$events],$this->headers($u))->assertUnprocessable();$this->assertSame([],Json::read(DB::table('attempts')->where('id',$a['id'])->value('placed')));}
    public function test_countdown_expiry_fails_and_pause_does_not_spend_game_time(): void {$u=$this->guest();$a=$this->start($u);$this->travel(10)->seconds();$paused=$this->postJson('/api/v1/attempts/'.$a['id'].'/clock',['action'=>'pause'],$this->headers($u))->assertOk()->json();$this->travel(100)->seconds();$view=$this->getJson('/api/v1/attempts/'.$a['id'],$this->headers($u))->assertOk()->json();$this->assertSame($paused['elapsed_ms'],$view['elapsed_ms']);$this->postJson('/api/v1/attempts/'.$a['id'].'/clock',['action'=>'resume'],$this->headers($u))->assertOk();$this->travel(361)->seconds();$this->postJson('/api/v1/attempts/'.$a['id'].'/events',['events'=>$this->events($a['id'])],$this->headers($u))->assertOk()->assertJsonPath('state','timed_out');$this->assertDatabaseCount('progress',0);}
    public function test_hint_only_counts_when_consumed_and_caps_rating(): void {$u=$this->guest();$a=$this->start($u);$this->postJson('/api/v1/attempts/'.$a['id'].'/assistance',['type'=>'hint'],$this->headers($u))->assertOk();$result=$this->complete($u,$a['id']);$this->assertSame(2,$result['rating']);$this->assertSame(1,$result['wallet']['hints']);}
    public function test_shuffle_purchase_is_atomic_and_requires_paused_attempt(): void {$u=$this->guest();$a=$this->start($u);$this->postJson('/api/v1/attempts/'.$a['id'].'/assistance',['type'=>'shuffle','confirm_purchase'=>true],$this->headers($u))->assertConflict();$this->postJson('/api/v1/attempts/'.$a['id'].'/clock',['action'=>'pause'],$this->headers($u))->assertOk();$this->postJson('/api/v1/attempts/'.$a['id'].'/assistance',['type'=>'shuffle','confirm_purchase'=>true],$this->headers($u))->assertOk()->assertJsonPath('wallet.coins',150);$this->assertSame(1,DB::table('attempts')->where('id',$a['id'])->value('shuffles_used'));}
    public function test_daily_rewards_are_single_claim_utc_and_missing_days_do_not_reset(): void {$u=$this->guest();$this->postJson('/api/v1/rewards/daily/claim',[],$this->headers($u))->assertOk()->assertJsonPath('wallet.coins',350);$this->postJson('/api/v1/rewards/daily/claim',[],$this->headers($u))->assertConflict();$this->travel(3)->days();$this->postJson('/api/v1/rewards/daily/claim',[],$this->headers($u))->assertOk()->assertJsonPath('wallet.coins',425);}
    public function test_village_upgrade_uses_confirmed_goal_and_expected_stage(): void {$u=$this->guest();$this->postJson('/api/v1/village/cottage/upgrade',['expected_stage'=>0],$this->headers($u))->assertConflict();$a=$this->start($u);$this->complete($u,$a['id']);$this->postJson('/api/v1/village/cottage/upgrade',['expected_stage'=>0],$this->headers($u))->assertOk()->assertJsonPath('stage',1)->assertJsonPath('wallet.coins',700);$this->postJson('/api/v1/village/cottage/upgrade',['expected_stage'=>0],$this->headers($u))->assertConflict();}
    public function test_paid_preview_does_not_consume_on_open_and_resumes_same_attempt(): void {$u=$this->guest();$a=$this->start($u);$this->postJson('/api/v1/shop/purchases',['offer_id'=>'full_image'],$this->headers($u))->assertOk();$result=$this->postJson('/api/v1/attempts/'.$a['id'].'/preview/activate',[],$this->headers($u))->assertOk()->json();$this->assertSame(30000,$result['remaining_ms']);$this->travel(5)->seconds();$paused=$this->postJson('/api/v1/previews/'.$result['id'].'/lifecycle',['visible_elapsed_ms'=>5000,'action'=>'pause'],$this->headers($u))->assertOk()->json();$this->assertSame(25000,$paused['remaining_ms']);$this->travel(10)->seconds();$this->postJson('/api/v1/attempts/'.$a['id'].'/preview/activate',['entitlement_id'=>$result['id']],$this->headers($u))->assertOk()->assertJsonPath('remaining_ms',25000);$this->assertSame(1,DB::table('attempts')->where('id',$a['id'])->value('full_images_used'));}
    public function test_offline_journal_is_bounded_and_never_enters_weekly_rank(): void {$u=$this->guest();$a=$this->start($u,'green_valley_house_001',true);$this->travel(120)->seconds();$this->postJson('/api/v1/attempts/'.$a['id'].'/offline/sync',['journal'=>$this->events($a['id']),'elapsed_ms'=>100000,'allocations'=>[]],$this->headers($u))->assertOk()->assertJsonPath('rank_verified',false)->assertJsonPath('wallet.coins',800);}
    public function test_unverified_registered_player_has_no_confirmed_rewards(): void {$u=$this->guest();DB::table('users')->where('id',$u['player']['id'])->update(['is_guest'=>false,'email'=>'unverified@example.com']);$this->postJson('/api/v1/rewards/daily/claim',[],$this->headers($u))->assertForbidden();$this->assertSame(300,app(Wallet::class)->balance($u['player']['id'])['coins']);}
    public function test_otp_bad_attempts_persist_and_single_use_success_cannot_replay(): void {$u=$this->guest();$uid=$u['player']['id'];DB::table('users')->where('id',$uid)->update(['is_guest'=>false,'email'=>'test@example.com']);$code=null;Event::listen(\Illuminate\Mail\Events\MessageSending::class,function($event)use(&$code){preg_match('/code: (\d{6})/',$event->message->getTextBody(),$matches);$code=$matches[1]??null;});$challenge=app(Identity::class)->issueOtp('test@example.com','email_verification');$this->assertNotNull($code);$wrong=$code==='111111'?'222222':'111111';for($i=0;$i<4;$i++)$this->postJson('/api/v1/auth/otp/verify',['challenge_id'=>$challenge['challenge_id'],'purpose'=>'email_verification','code'=>$wrong])->assertUnprocessable();$this->assertSame(4,DB::table('otp_challenges')->where('id',$challenge['challenge_id'])->value('attempts'));$this->postJson('/api/v1/auth/otp/verify',['challenge_id'=>$challenge['challenge_id'],'purpose'=>'email_verification','code'=>$code])->assertOk();$this->postJson('/api/v1/auth/otp/verify',['challenge_id'=>$challenge['challenge_id'],'purpose'=>'email_verification','code'=>$code])->assertUnprocessable();}
    public function test_deleted_or_revoked_token_cannot_access_any_player_data(): void {$u=$this->guest();$this->postJson('/api/v1/auth/logout',[],$this->headers($u))->assertOk();$this->getJson('/api/v1/me',$this->headers($u))->assertUnauthorized();}
    public function test_dst_fold_and_gap_have_deterministic_utc_conversion(): void {$this->assertSame('2026-11-01 05:30',LocalSchedule::utc('2026-11-01 01:30','America/New_York')->format('Y-m-d H:i'));$this->assertSame('2026-03-08 07:00',LocalSchedule::utc('2026-03-08 02:30','America/New_York')->format('Y-m-d H:i'));$this->assertSame('2026-11-25 15:00',LocalSchedule::utc('2026-11-25 18:00','Asia/Kuwait')->format('Y-m-d H:i'));}
    public function test_ssv_requires_real_signature_and_duplicate_callback_never_grants_twice(): void {$u=$this->guest();$a=$this->start($u);config(['puzzlequest.ad_units'=>['12345']]);$request=$this->postJson('/api/v1/ads/requests',['attempt_id'=>$a['id'],'type'=>'hint'],$this->headers($u))->assertCreated()->json();$key=openssl_pkey_new(['config'=>__DIR__.'/../Fixtures/openssl.cnf','private_key_type'=>OPENSSL_KEYTYPE_EC,'curve_name'=>'prime256v1']);$public=openssl_pkey_get_details($key)['key'];Cache::put('admob:ssv:keys',[['keyId'=>7,'pem'=>$public]],3600);$query=http_build_query(['ad_network'=>'1','ad_unit'=>'12345','custom_data'=>$request['reward_request_id'],'reward_amount'=>'1','reward_item'=>'hint','timestamp'=>(string)(now()->timestamp*1000),'transaction_id'=>'transaction-1','user_id'=>(string)$u['player']['id']],'','&',PHP_QUERY_RFC3986);openssl_sign($query,$signature,$key,OPENSSL_ALGO_SHA256);$url='/api/v1/ads/ssv?'.$query.'&signature='.rtrim(strtr(base64_encode($signature),'+/','-_'),'=').'&key_id=7';$this->getJson($url)->assertOk();$this->getJson($url)->assertOk()->assertJsonPath('duplicate',true);$this->assertSame(3,app(Wallet::class)->balance($u['player']['id'])['hints']);$this->getJson(str_replace('reward_amount=1','reward_amount=2',$url))->assertBadRequest();}
    public function test_private_profiles_and_guests_are_not_in_weekly_global(): void {$u=$this->guest();$a=$this->start($u);$this->complete($u,$a['id']);$this->getJson('/api/v1/leaderboard/weekly',$this->headers($u))->assertOk()->assertJsonCount(0,'rows');DB::table('users')->where('id',$u['player']['id'])->update(['is_guest'=>false,'email_verified_at'=>now(),'visibility'=>'public']);$this->getJson('/api/v1/leaderboard/weekly',$this->headers($u))->assertOk()->assertJsonCount(1,'rows');$this->getJson('/api/v1/leaderboard/all-time',$this->headers($u))->assertNotFound();}
}
